<?php
require_once __DIR__ . '/../lib/bootstrap.php';
require_role('teacher','admin');
$uid=(int)current_user()['id'];$examId=get_int('exam_id');
function normalize_review_text($text){$text=strtr((string)$text,['ي'=>'ی','ى'=>'ی','ك'=>'ک','ۀ'=>'ه','ة'=>'ه','ؤ'=>'و','إ'=>'ا','أ'=>'ا','‌'=>' ']);$text=preg_replace('/[\x{064B}-\x{065F}]/u','',$text);$text=preg_replace('/[^\p{L}\p{N}\s]/u',' ',$text);$text=preg_replace('/\s+/u',' ',trim($text));return mb_strtolower($text,'UTF-8');}
function suggested_short_score($answer,$rubric,$max){$answer=normalize_review_text($answer);$found=[];$score=0;foreach(preg_split('/\R/u',(string)$rubric) as $line){$line=trim($line);if($line==='')continue;$parts=explode('|',$line,2);$keyword=normalize_review_text($parts[0]??'');$points=(float)($parts[1]??0);if($keyword!==''&&mb_strpos($answer,$keyword)!==false){$score+=$points;$found[]=$parts[0];}}return ['score'=>min($max,max(0,$score)),'found'=>$found];}
$ownerSql=current_user()['role']==='admin'?'':' AND e.created_by=?';$params=current_user()['role']==='admin'?[$examId]:[$examId,$uid];$s=db()->prepare("SELECT e.*,s.title subject_title,c.title class_title FROM exams e JOIN subjects s ON s.id=e.subject_id JOIN classes c ON c.id=e.class_id WHERE e.id=?$ownerSql");$s->execute($params);$exam=$s->fetch();if(!$exam)exit('آزمون پیدا نشد یا دسترسی ندارید.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$answerId=(int)($_POST['answer_id']??0);$score=max(0,(float)($_POST['awarded_score']??0));$comment=post_string('teacher_comment');$s=db()->prepare('SELECT a.id,a.attempt_id,at.student_id,at.exam_id,q.score,q.question_type FROM answers a JOIN questions q ON q.id=a.question_id JOIN attempts at ON at.id=a.attempt_id WHERE a.id=? AND at.exam_id=? AND q.question_type="short"');$s->execute([$answerId,$examId]);$row=$s->fetch();if($row){$score=min($score,(float)$row['score']);$u=db()->prepare('UPDATE answers SET awarded_score=?,is_correct=?,teacher_comment=? WHERE id=?');$u->execute([$score,$score>0?1:0,$comment,$answerId]);$sum=db()->prepare('SELECT COALESCE(SUM(awarded_score),0) score FROM answers WHERE attempt_id=?');$sum->execute([$row['attempt_id']]);$total=(float)$sum->fetchColumn();$pct=$exam['total_score']>0?($total/(float)$exam['total_score']*100):0;$left=db()->prepare('SELECT COUNT(*) FROM answers a JOIN questions q ON q.id=a.question_id WHERE a.attempt_id=? AND q.question_type="short" AND a.awarded_score IS NULL');$left->execute([$row['attempt_id']]);$status=(int)$left->fetchColumn()===0?'reviewed':'submitted';$u=db()->prepare('UPDATE attempts SET score=?,percentage=?,status=? WHERE id=?');$u->execute([$total,$pct,$status,$row['attempt_id']]);notify_user((int)$row['student_id'],'نمره و بازخورد شما به‌روزرسانی شد','معلم پاسخ تشریحی شما را بررسی و نمره یا بازخورد جدید ثبت کرد.','student/result.php?id='.$row['attempt_id'],'grade_updated');audit('review_short_answer','answer',$answerId);flash('success','نمره و بازخورد پاسخ ذخیره شد.');}else flash('error','پاسخ معتبر پیدا نشد.');redirect('teacher/review_short_answers.php?exam_id='.$examId);}
$s=db()->prepare('SELECT a.id answer_id,a.attempt_id,a.answer_text,a.awarded_score,a.teacher_comment,q.question_text,q.score q_score,q.reference_answer,q.rubric,u.full_name student_name,u.mobile FROM answers a JOIN attempts at ON at.id=a.attempt_id JOIN questions q ON q.id=a.question_id JOIN users u ON u.id=at.student_id WHERE at.exam_id=? AND q.question_type="short" ORDER BY u.full_name,at.id,q.sort_order');$s->execute([$examId]);$answers=$s->fetchAll();foreach($answers as &$answer){$r=suggested_short_score($answer['answer_text'],$answer['rubric'],$answer['q_score']);$answer['suggested_score']=$r['score'];$answer['found']=$r['found'];}unset($answer);$title='بررسی پاسخ‌های کوتاه';require __DIR__.'/../partials/header.php';?><div class="card class-toolbar"><div><span class="eyebrow">ارزیابی تشریحی</span><h1>بررسی پاسخ‌های کوتاه</h1><p class="muted"><?=e($exam['title'])?> — <?=e($exam['subject_title'])?> — <?=e($exam['class_title'])?></p></div><a class="btn btn-light" href="<?=e(url('teacher/exams.php?id='.$examId))?>">بازگشت به آزمون</a></div><div class="card"><p class="muted">نمرهٔ پیشنهادی فقط بر اساس کلمات کلیدی Rubric محاسبه می‌شود و قبل از ثبت باید توسط معلم بررسی شود.</p><?php if(!$answers):?><p>هنوز پاسخ کوتاهی برای بررسی وجود ندارد.</p><?php endif;?><?php foreach($answers as $i=>$a):?><div class="question"><h3><?=e($a['student_name'])?> — سؤال <?=($i+1)?></h3><p><strong><?=e($a['question_text'])?></strong></p><p>پاسخ دانش‌آموز:</p><blockquote><?=nl2br(e($a['answer_text']??'بدون پاسخ'))?></blockquote><p class="muted">پاسخ مرجع: <?=e($a['reference_answer']??'ثبت نشده')?></p><p class="muted">معیارهای یافت‌شده: <?=e($a['found']?implode('، ',$a['found']):'هیچ‌کدام')?> | نمرهٔ پیشنهادی: <?=format_score($a['suggested_score'])?> از <?=format_score($a['q_score'])?></p><form method="post" class="grid grid-2"><?=csrf_field()?><input type="hidden" name="answer_id" value="<?=$a['answer_id']?>"><div class="form-group"><label>نمرهٔ نهایی</label><input type="number" name="awarded_score" step="0.01" min="0" max="<?=e($a['q_score'])?>" value="<?=e((string)($a['awarded_score']??$a['suggested_score']))?>"></div><div class="form-group"><label>بازخورد معلم</label><textarea name="teacher_comment" placeholder="بازخورد اختیاری"><?=e($a['teacher_comment']??'')?></textarea></div><button class="btn btn-success">ذخیره نمره و بازخورد</button></form></div><?php endforeach;?></div><?php require __DIR__.'/../partials/footer.php'; ?>
